import{_ as t,o,c as i,a2 as n}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"Epic: Design System & Branding","description":"","frontmatter":{},"headers":[],"relativePath":"sovereign-edge/epics/design-system.md","filePath":"sovereign-edge/epics/design-system.md"}'),a={name:"sovereign-edge/epics/design-system.md"};function s(r,e,d,c,l,h){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="epic-design-system-branding" tabindex="-1">Epic: Design System &amp; Branding <a class="header-anchor" href="#epic-design-system-branding" aria-label="Permalink to &quot;Epic: Design System &amp; Branding&quot;">​</a></h1><blockquote><p>A native RN theme adapting Sovereign&#39;s visual identity — the app is fully standalone, but may look and feel like part of the same family.</p></blockquote><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>⏳ In Progress</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Per the developer&#39;s decision in research 0001: Sovereign Edge is a fully independent app with no runtime dependency on <code>sovereign</code>, but may reuse Sovereign&#39;s visual identity. <code>@sovereignfs/ui</code> itself (CSS Modules + web React components) isn&#39;t usable in React Native directly — this epic is about porting the <em>token values and visual language</em> (monochrome identity, the <code>--sv-*</code> scale) into a native theme system, not importing the web package.</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="✅-7-1-—-native-theme-tokens" tabindex="-1">✅ 7.1 — Native theme tokens <a class="header-anchor" href="#✅-7-1-—-native-theme-tokens" aria-label="Permalink to &quot;✅ 7.1 — Native theme tokens&quot;">​</a></h4><p><strong>Goal:</strong> Port Sovereign&#39;s token values (spacing, radius, font-size scale, monochrome color identity) into an RN-native theme (e.g. a plain TS theme object / RN StyleSheet constants), without importing <code>@sovereignfs/ui</code> itself.</p><p><strong>Deliverables:</strong></p><ul><li>A theme module mirroring <code>sovereign</code>&#39;s primitive/semantic two-tier token structure conceptually, values ported by hand rather than shared at the code level.</li><li>Light/dark mode support, matching Sovereign&#39;s existing dark-mode override pattern.</li></ul><p><strong>Dependencies:</strong> none within this epic.</p><p><strong>Review checklist:</strong></p><ul><li>✅ Switching light/dark mode restyles the whole app from the semantic theme layer, with no per-component hardcoded colors. Verified on an Android emulator by toggling the system setting (<code>cmd uimode night yes</code>) without restarting the app: the surface inverted from white to <code>#09090b</code> and body text from grey-950 to grey-50, driven entirely by the semantic tier. <code>App.tsx</code> keeps only layout in <code>StyleSheet</code>; every colour and type value comes from <code>useTheme()</code>.</li></ul><hr><h4 id="✅-7-2-—-core-component-set" tabindex="-1">✅ 7.2 — Core component set <a class="header-anchor" href="#✅-7-2-—-core-component-set" aria-label="Permalink to &quot;✅ 7.2 — Core component set&quot;">​</a></h4><p><strong>Goal:</strong> The minimum native component set the chat and settings UI need.</p><p><strong>Deliverables:</strong></p><ul><li>Button, input, chat bubble, list item, toggle, and similar primitives built on Task 7.1&#39;s theme, styled consistently with the wider Sovereign identity without being the same code.</li></ul><p><strong>Dependencies:</strong> Task 7.1.</p><p><strong>Review checklist:</strong></p><ul><li>✅ No screen in the app hardcodes a color, spacing, or radius value outside the theme module. Enforced by lint rather than inspection: <code>eslint.config.js</code> rejects hex/<code>rgb()</code>/<code>hsl()</code> literals anywhere under <code>src/</code> except <code>src/design-system/</code>, where defining them is the job. Verified the rule fires by planting a violation, not just by seeing it pass.</li></ul><p><strong>Known deviation:</strong> <code>Toggle</code> wraps the platform <code>Switch</code> and is deliberately untinted, so it shows the OS accent rather than Sovereign&#39;s monochrome one. Two attempts to theme it were worse: Android alpha-blends <code>trackColor</code>, which made a near-white <code>accent</code> track invisible in dark mode, and it does not reliably honour <code>thumbColor</code> — leaving a white thumb on an invisible track. Platform colours are legible in both schemes; matching the identity here needs a custom Pressable-based toggle, not more props.</p><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./../../CONCEPT.html">CONCEPT.md</a></li><li><a href="./../research/0001-concept-and-connector-architecture.html">research 0001</a></li></ul>',25)])])}const g=t(a,[["render",s]]);export{p as __pageData,g as default};
